// === Konfiguration: hier deine Werte eintragen ===
const CONFIG = {
  pipelineBin: '/opt/clip-pipeline/bin/pipeline',
  telegramChatId: 'DEINE_CHAT_ID',
};

// Nur eine geprüfte Session-ID wird weitergegeben.
// Grund: Der Wert landet später in einem Shell-Befehl auf dem Heimserver.
// Ungeprüfte Eingaben könnten dort eigene Befehle einschleusen
// ("Command Injection"). Erlaubt: Buchstaben, Ziffern, . _ - (kein Punkt am Anfang).
const body = $input.first().json.body ?? {};
const session = String(body.session ?? '').trim();
if (!/^[A-Za-z0-9][A-Za-z0-9._-]{0,79}$/.test(session)) {
  throw new Error(`Ungültige Session-ID: "${session}"`);
}

return [{ json: { ...CONFIG, session } }];

// Vertrag: Jedes Pipeline-Skript schreibt Logs nach stderr und gibt als
// LETZTE Zeile auf stdout genau eine JSON-Zeile aus. Exit-Code 0 = ok.
const r = $input.first().json;
if (r.code !== 0) {
  throw new Error(`Exit-Code ${r.code}: ${(r.stderr || '').slice(-800)}`);
}
const zeilen = (r.stdout || '').trim().split('\n');
const letzte = zeilen[zeilen.length - 1];
try {
  return [{ json: JSON.parse(letzte) }];
} catch (e) {
  throw new Error('Letzte Ausgabezeile ist kein JSON: ' + letzte);
}

